INSERT INTO public.semantic_catalog ("id", "object_name", "column_name", "title", "description", "tags", "owner", "sensitivity", "source_tables", "iso_standard", "updated_at") VALUES ('65e8bcbb-201e-420a-8a10-0bfa45866395', 'sem_failure_events', NULL, 'Failure Events', 'Canonical ISO 14224 failure-event log: one row per work order carrying failure coding, with failure mode, cause and remedy decoded to plain language, plus downtime hours and event cost. Use this — not raw work_orders — for reliability analysis (Pareto, MTBF, Weibull inputs).', '{reliability,failures,iso14224}', 'Reliability Engineering', 'internal', '{work_orders,wo_failure_data,assets,reference_codes,dictionaries,work_centers}', 'ISO 14224', '2026-07-08 12:58:14.113928+00') ON CONFLICT DO NOTHING;
INSERT INTO public.semantic_catalog ("id", "object_name", "column_name", "title", "description", "tags", "owner", "sensitivity", "source_tables", "iso_standard", "updated_at") VALUES ('564ca130-15b3-4645-9b32-d502dc6d380a', 'sem_failure_events', 'event_cost', NULL, 'Total maintenance cost of the event = frozen labor cost + frozen material cost. Frozen values are locked at WO closure; 0 when costs were never captured.', '{cost}', NULL, 'internal', '{work_orders}', NULL, '2026-07-08 12:58:14.113928+00') ON CONFLICT DO NOTHING;
INSERT INTO public.semantic_catalog ("id", "object_name", "column_name", "title", "description", "tags", "owner", "sensitivity", "source_tables", "iso_standard", "updated_at") VALUES ('a501f8f0-0769-4818-8aad-54c6f765a7b1', 'sem_failure_events', 'failure_mode', NULL, 'Decoded ISO 14224 failure-mode description (reference_codes, category FAILURE_MODE). NULL when the coded value has no dictionary entry.', '{iso14224}', NULL, 'internal', '{reference_codes}', 'ISO 14224', '2026-07-08 12:58:14.113928+00') ON CONFLICT DO NOTHING;
INSERT INTO public.semantic_catalog ("id", "object_name", "column_name", "title", "description", "tags", "owner", "sensitivity", "source_tables", "iso_standard", "updated_at") VALUES ('c9af87b5-982f-4129-902a-3bbe97de1d56', 'sem_work_history', NULL, 'Work History', 'Canonical maintenance work-order history: every WO with asset, work group, type, status, cost and downtime. recurring_work_id non-null means PM-generated; request_id non-null means it originated from a service request.', '{maintenance,work-orders}', 'Maintenance', 'internal', '{work_orders,assets,work_centers}', NULL, '2026-07-08 12:58:14.113928+00') ON CONFLICT DO NOTHING;
INSERT INTO public.semantic_catalog ("id", "object_name", "column_name", "title", "description", "tags", "owner", "sensitivity", "source_tables", "iso_standard", "updated_at") VALUES ('b07d8df6-25a8-4f9f-b138-965c94679c93', 'sem_readings', NULL, 'Condition Readings', 'Condition-monitoring readings decoded against their reading-point thresholds. breach_severity is the canonical interpretation: CRITICAL / WARNING / NORMAL (thresholds left NULL are not evaluated).', '{condition-monitoring,readings}', 'Reliability Engineering', 'internal', '{reading_logs,reading_definitions,assets}', NULL, '2026-07-08 12:58:14.113928+00') ON CONFLICT DO NOTHING;
INSERT INTO public.semantic_catalog ("id", "object_name", "column_name", "title", "description", "tags", "owner", "sensitivity", "source_tables", "iso_standard", "updated_at") VALUES ('a8ae1a99-79a5-4c0c-8d09-d8e311cafffa', 'sem_readings', 'breach_severity', NULL, 'CRITICAL when the value crosses min/max_critical, WARNING when it crosses min/max_warning, else NORMAL. This is the single source of truth for alarm interpretation.', '{alarms}', NULL, 'internal', '{reading_definitions}', NULL, '2026-07-08 12:58:14.113928+00') ON CONFLICT DO NOTHING;
INSERT INTO public.semantic_catalog ("id", "object_name", "column_name", "title", "description", "tags", "owner", "sensitivity", "source_tables", "iso_standard", "updated_at") VALUES ('9ff66e8a-26a5-4790-8903-b5fae2d52e95', 'sem_pm_compliance', NULL, 'PM Compliance', 'Active recurring work (PM strategies) with schedule and due status. is_overdue = next_due_date in the past. Use for backlog and compliance KPIs.', '{pm,compliance}', 'Maintenance Planning', 'internal', '{recurring_work,assets,work_centers}', NULL, '2026-07-08 12:58:14.113928+00') ON CONFLICT DO NOTHING;
INSERT INTO public.semantic_catalog ("id", "object_name", "column_name", "title", "description", "tags", "owner", "sensitivity", "source_tables", "iso_standard", "updated_at") VALUES ('3de07cff-be3a-42b4-af51-7bbd49c383db', 'sem_asset_health', NULL, 'Asset Health', 'One row per asset: criticality, reliability KPIs (MTBF days, MTTR hours, YTD failure count, running hours), open work-order count, failure events and downtime over the trailing 12 months, overdue PM count, and the timestamp of the last condition reading.', '{assets,kpi,reliability}', 'Reliability Engineering', 'internal', '{assets,work_orders,wo_failure_data,recurring_work,reading_logs,work_centers}', NULL, '2026-07-08 12:58:14.113928+00') ON CONFLICT DO NOTHING;
INSERT INTO public.semantic_catalog ("id", "object_name", "column_name", "title", "description", "tags", "owner", "sensitivity", "source_tables", "iso_standard", "updated_at") VALUES ('18075f16-a839-45c0-9608-1c58d3ba0ddb', 'sem_asset_health', 'criticality', NULL, 'Asset criticality class A (highest) to D (lowest). Drives monitoring cadence and prioritization; NULL when unassessed.', '{criticality}', NULL, 'internal', '{assets}', NULL, '2026-07-08 12:58:14.113928+00') ON CONFLICT DO NOTHING;
INSERT INTO public.semantic_catalog ("id", "object_name", "column_name", "title", "description", "tags", "owner", "sensitivity", "source_tables", "iso_standard", "updated_at") VALUES ('e25f4f53-4b1f-42d4-b410-8f22ea936464', 'psc_metrics', NULL, 'Potential Success Curve (PSC)', 'Success-centric reliability framework (Olorunfemi, 2026): instead of only asking "when will this asset fail?", PSC measures how long an asset SUSTAINS optimal performance. An asset''s Golden Spot is its optimal performance envelope, defined by the warning bands (min/max_warning) of its condition reading points; critical bands mark Critical Departure. Zones: In Golden Spot → Sub-Optimal Drift → Critical Departure → Restored. Complements (never replaces) failure-centric RCM analysis; failure analysis remains authoritative for safety-critical scenarios.', '{psc,reliability,golden-spot,success-centric}', 'Reliability Engineering', 'internal', '{reading_definitions,reading_logs,assets}', 'ISO 55000:2024', '2026-07-09 12:48:03.169868+00') ON CONFLICT DO NOTHING;
INSERT INTO public.semantic_catalog ("id", "object_name", "column_name", "title", "description", "tags", "owner", "sensitivity", "source_tables", "iso_standard", "updated_at") VALUES ('31dcf9e4-2bfc-4e47-8ab9-ef9e8b65af27', 'psc_metrics', 'mtop', 'Mean Time of Optimal Performance', 'MTOP = Σ(time in Golden Spot) / N in-spot periods (Eq. 1). The success-centric complement to MTBF: average duration the asset holds ALL banded parameters inside their optimal bands. Computed from time-stamped reading_logs evaluated against reading_definitions bands; an in-spot period ends at a Success Departure (any parameter leaving its optimal band).', '{psc,kpi}', NULL, 'internal', '{reading_logs,reading_definitions}', 'ISO 55000:2024', '2026-07-09 12:48:03.169868+00') ON CONFLICT DO NOTHING;
INSERT INTO public.semantic_catalog ("id", "object_name", "column_name", "title", "description", "tags", "owner", "sensitivity", "source_tables", "iso_standard", "updated_at") VALUES ('f5d19e8a-4860-4418-b8b4-7383219721ce', 'psc_metrics', 'mttrg', 'Mean Time to Restore Golden Spot', 'MTTRg = Σ(restoration duration) / N completed restorations (Eq. 2). Extends MTTR: average time from Success Departure until every parameter is back inside its optimal band. Only completed restorations count; a departure still in progress is reported separately.', '{psc,kpi}', NULL, 'internal', '{reading_logs,reading_definitions}', 'ISO 55000:2024', '2026-07-09 12:48:03.169868+00') ON CONFLICT DO NOTHING;
INSERT INTO public.semantic_catalog ("id", "object_name", "column_name", "title", "description", "tags", "owner", "sensitivity", "source_tables", "iso_standard", "updated_at") VALUES ('81aedde2-b80b-406b-9652-22a4cb0a159c', 'psc_metrics', 'success_rate', 'Success Rate (SR)', 'SR = MTOP / (MTOP + MTTRg) × 100% (Eq. 3). Availability measured against OPTIMAL performance rather than mere functioning. Targets per the framework: ≥90% on target, ≥95% world-class. Null until at least one complete departure-and-restoration cycle has been observed.', '{psc,kpi}', NULL, 'internal', '{reading_logs,reading_definitions}', 'ISO 55000:2024', '2026-07-09 12:48:03.169868+00') ON CONFLICT DO NOTHING;
INSERT INTO public.semantic_catalog ("id", "object_name", "column_name", "title", "description", "tags", "owner", "sensitivity", "source_tables", "iso_standard", "updated_at") VALUES ('77eb5b87-4afc-43d3-86cc-e92c345678f4', 'psc_metrics', 'ope', 'Overall Performance Excellence (OPE)', 'OPE = SR × PQ × EE (Eq. 4), where PQ is Production Quality and EE is Energy Efficiency (actual vs optimal consumption). Extends OEE with an energy dimension supporting the ISO 55000:2024 sustainability outcome. Target ≥85%. Not computed until PQ and EE data sources exist — values are never fabricated.', '{psc,kpi,sustainability}', NULL, 'internal', '{reading_logs,reading_definitions}', 'ISO 55000:2024', '2026-07-09 12:48:03.169868+00') ON CONFLICT DO NOTHING;
INSERT INTO public.semantic_catalog ("id", "object_name", "column_name", "title", "description", "tags", "owner", "sensitivity", "source_tables", "iso_standard", "updated_at") VALUES ('73671b40-28da-4cbf-9f0d-572783bcba51', 'ers_smea_items', 'spn', 'Success Priority Number', 'SPN = Value Impact × Sustainability × Monitorability (each 1-10; max 1000). Prioritizes the conditions that SUSTAIN optimal performance. Monitorability is scored directly — a continuously monitorable condition scores HIGH because it can be actively managed, the inversion of FMEA Detectability. Generated column; the math cannot drift.', '{psc,smea,kpi}', 'Reliability Engineering', 'internal', '{ers_smea_items}', 'ISO 55000:2024', '2026-07-09 12:50:32.022687+00') ON CONFLICT DO NOTHING;
INSERT INTO public.semantic_catalog ("id", "object_name", "column_name", "title", "description", "tags", "owner", "sensitivity", "source_tables", "iso_standard", "updated_at") VALUES ('402eb97e-c372-4be0-b0d0-42426465fb8f', 'work_center_members', NULL, 'Work Center Crew', 'Operational assignment of people to work centers — the bridge between the org chart (administrative home) and work centers (execution resources). A person may serve on several crews; one member may be flagged LEAD. Independent of org-unit membership by design.', '{work-centers,people,crew}', 'Maintenance', 'internal', '{work_center_members,work_centers,contacts}', NULL, '2026-07-09 21:33:27.17218+00') ON CONFLICT DO NOTHING;
INSERT INTO public.semantic_catalog ("id", "object_name", "column_name", "title", "description", "tags", "owner", "sensitivity", "source_tables", "iso_standard", "updated_at") VALUES ('e1b55aa8-b101-480d-9db7-20663b7b5e93', 'messages', NULL, 'Contextual Messages', 'Append-only team conversation anchored to a work object (work order, service request, RCA, asset, or work group). The thread is part of the maintenance record — permanent, searchable, and usable as RCA evidence. Field teams communicate where the work is, so knowledge accrues to the asset instead of evaporating in external chat.', '{collaboration,messaging}', 'Maintenance', 'internal', '{messages,thread_reads}', 'ISO 55013:2024', '2026-07-26 07:15:55.642831+00') ON CONFLICT DO NOTHING;
INSERT INTO public.semantic_catalog ("id", "object_name", "column_name", "title", "description", "tags", "owner", "sensitivity", "source_tables", "iso_standard", "updated_at") VALUES ('d8ea0a2b-b65b-40e0-8f1c-3a9751dca466', 'sem_work_orders', 'wo_state', 'Work-order state', 'Canonical lifecycle bucket: open (work still owed, INCLUDING unrecognised statuses), done (performed and finished), void (cancelled/rejected — neither backlog nor completion). One definition shared by the dashboard, reports, the reliability digest and the mission engine. Mirrors src/lib/woState.ts.', '{work_management,canonical}', NULL, 'internal', '{work_orders}', 'ISO 14224', '2026-07-29 13:39:57.622183+00') ON CONFLICT DO NOTHING;
INSERT INTO public.semantic_catalog ("id", "object_name", "column_name", "title", "description", "tags", "owner", "sensitivity", "source_tables", "iso_standard", "updated_at") VALUES ('28d44d80-68a1-4373-9602-8afd43c90ef9', 'sem_work_orders', 'is_open', 'Open work order', 'TRUE when the work order is backlog: state open or unknown. An unmapped status counts as open on purpose — work that cannot be proven finished is still owed, and hiding it would silently shrink the backlog after an import.', '{work_management,canonical,kpi}', NULL, 'internal', '{work_orders}', 'ISO 14224', '2026-07-29 13:39:57.622183+00') ON CONFLICT DO NOTHING;
INSERT INTO public.semantic_catalog ("id", "object_name", "column_name", "title", "description", "tags", "owner", "sensitivity", "source_tables", "iso_standard", "updated_at") VALUES ('bfb84e70-864c-4132-bbb0-990a5035881e', 'sem_asset_reliability', NULL, 'Asset Reliability (computed)', 'Per-asset MTBF, MTTR and inherent availability computed from the last 365 days of corrective work orders. Operating hours = calendar year less recorded downtime (no run-hour meters), failures = corrective events, MTTR averaged over repairs that carry a duration. Same definitions as src/lib/reliabilityKpis.ts.', '{reliability,kpi,canonical}', 'Reliability Engineering', 'internal', '{work_orders,assets}', 'ISO 14224', '2026-07-29 15:39:05.113116+00') ON CONFLICT DO NOTHING;
INSERT INTO public.semantic_catalog ("id", "object_name", "column_name", "title", "description", "tags", "owner", "sensitivity", "source_tables", "iso_standard", "updated_at") VALUES ('1019fcdf-d574-4041-b9e6-5d517cd99f2c', 'sem_asset_reliability', 'mtbf_hours', 'MTBF', 'Mean operating time between corrective failures. NULL when the asset had no failures in the window — an honest absence, never 0.', '{reliability,kpi}', NULL, 'internal', '{work_orders}', 'ISO 14224', '2026-07-29 15:39:05.113116+00') ON CONFLICT DO NOTHING;
INSERT INTO public.semantic_catalog ("id", "object_name", "column_name", "title", "description", "tags", "owner", "sensitivity", "source_tables", "iso_standard", "updated_at") VALUES ('46067eea-e4d5-4407-9894-b85afe5a81f9', 'sem_asset_reliability', 'downtime_coverage_pct', 'Downtime coverage', 'Share of corrective events carrying a downtime figure. Low coverage means MTTR and availability rest on a thin denominator — quote them with that caveat.', '{data_quality}', NULL, 'internal', '{work_orders}', NULL, '2026-07-29 15:39:05.113116+00') ON CONFLICT DO NOTHING;
INSERT INTO public.semantic_catalog ("id", "object_name", "column_name", "title", "description", "tags", "owner", "sensitivity", "source_tables", "iso_standard", "updated_at") VALUES ('75e31568-f2ed-419a-a2c3-195711e57b46', 'sem_asset_health', 'mtbf_days', 'MTBF (days)', 'COMPUTED from the last 365 days of corrective work orders (sem_asset_reliability). Superseded the frozen assets.mtbf_days column, which migration 0108 filled once with a different formula and never refreshed; that legacy value is still visible as mtbf_days_stored.', '{reliability,kpi,canonical}', NULL, 'internal', '{work_orders,assets}', 'ISO 14224', '2026-07-29 15:39:05.113116+00') ON CONFLICT DO NOTHING;
INSERT INTO public.semantic_catalog ("id", "object_name", "column_name", "title", "description", "tags", "owner", "sensitivity", "source_tables", "iso_standard", "updated_at") VALUES ('c1ebb7de-048b-4e4a-82c9-1986b9e10f55', 'sem_asset_health', 'mtbf_days_stored', 'MTBF (days, legacy stored)', 'The frozen assets.mtbf_days column — a 2026 one-off backfill, not maintained. Kept for reference and reconciliation only; do not quote it.', '{legacy}', NULL, 'internal', '{assets}', NULL, '2026-07-29 15:39:05.113116+00') ON CONFLICT DO NOTHING;
INSERT INTO public.semantic_catalog ("id", "object_name", "column_name", "title", "description", "tags", "owner", "sensitivity", "source_tables", "iso_standard", "updated_at") VALUES ('6f0674fe-a8bb-4499-bae1-4965389e439b', 'sem_wo_settlement', 'settled_cost', 'Settled cost', 'How much of the actual cost has been posted to cost_allocations by settlement. Rises in deltas; never rewritten.', '{finops,canonical}', NULL, 'internal', '{cost_allocations}', NULL, '2026-08-02 11:12:35.387683+00') ON CONFLICT DO NOTHING;
INSERT INTO public.semantic_catalog ("id", "object_name", "column_name", "title", "description", "tags", "owner", "sensitivity", "source_tables", "iso_standard", "updated_at") VALUES ('3ef43e5a-f968-4247-83d8-74c64b2d7cbe', 'sem_wo_settlement', 'unsettled_variance', 'Unsettled variance', 'Actual cost that has not reached the ledger. Non-zero on a finished order means settlement has not caught up — the finance backlog, and the queue an ERP outbound adapter would drain.', '{finops,kpi,canonical}', NULL, 'internal', '{cost_allocations,work_orders}', NULL, '2026-08-02 11:12:35.387683+00') ON CONFLICT DO NOTHING;
INSERT INTO public.semantic_catalog ("id", "object_name", "column_name", "title", "description", "tags", "owner", "sensitivity", "source_tables", "iso_standard", "updated_at") VALUES ('bf9f64a5-19de-46b1-a7ec-d71037e26ae4', 'sem_stock_movements', 'movement_type', 'Movement type', 'SAP movement type (BWART) governing the stock direction and account assignment: 101 goods receipt, 201 issue to cost center, 261 issue to order, 311 transfer, 551 scrap, 561 opening balance, 701/702 count gain/loss, and their reversals.', '{inventory,finops,canonical}', NULL, 'internal', '{inventory_transactions,movement_types}', NULL, '2026-08-02 11:12:36.195034+00') ON CONFLICT DO NOTHING;
INSERT INTO public.semantic_catalog ("id", "object_name", "column_name", "title", "description", "tags", "owner", "sensitivity", "source_tables", "iso_standard", "updated_at") VALUES ('6a46bb7a-aa22-450c-b9a4-8aba3c51db39', 'sem_stock_movements', 'total_value', 'Movement value', 'Quantity x unit cost, signed as expense: positive when stock leaves the store, negative when it comes back. Zero on movements recorded before valuation was captured.', '{inventory,finops}', NULL, 'internal', '{inventory_transactions}', NULL, '2026-08-02 11:12:36.195034+00') ON CONFLICT DO NOTHING;
INSERT INTO public.semantic_catalog ("id", "object_name", "column_name", "title", "description", "tags", "owner", "sensitivity", "source_tables", "iso_standard", "updated_at") VALUES ('b4ce6ade-2988-43de-9e39-cafb374dde56', 'sem_stock_movements', 'fi_status', 'Financial posting status', 'Whether a movement has reached the cost ledger: "posted" (its own document), "settles with the order" (a work-order movement, posted by settlement so it cannot double count), "stock only" (no expense), "no value", or "unposted" — the exception queue.', '{inventory,finops,kpi}', NULL, 'internal', '{inventory_transactions,cost_allocations}', NULL, '2026-08-02 11:12:36.195034+00') ON CONFLICT DO NOTHING;
INSERT INTO public.semantic_catalog ("id", "object_name", "column_name", "title", "description", "tags", "owner", "sensitivity", "source_tables", "iso_standard", "updated_at") VALUES ('b5cb2532-ec59-468d-bc00-a14c688275c0', 'sem_wo_settlement', 'actual_cost', 'Work-order actual cost', 'Confirmed labour (hours x the rate posted with the confirmation), issued parts (quantity x unit cost), and received service-PO lines. The settlement basis — the same definition the work order Cost tab displays. Ordering a part or a service is a commitment and is excluded; only issue and receipt are cost.', '{finops,work_management,canonical}', NULL, 'internal', '{work_order_labor,work_order_parts,job_tasks,work_centers}', 'ISO 14224', '2026-08-02 11:12:35.387683+00') ON CONFLICT DO NOTHING;
INSERT INTO public.semantic_catalog ("id", "object_name", "column_name", "title", "description", "tags", "owner", "sensitivity", "source_tables", "iso_standard", "updated_at") VALUES ('a4327234-e492-4767-88a5-1989627434a1', 'sem_invoice_matches', 'match_status', 'Three-way match verdict', 'MATCHED (invoice agrees with the order and the receipts within tolerance), BLOCKED (a line is over-priced or claims more than was received), PENDING (no lines matched yet). Scored per line, because a header-only comparison nets a price error against a quantity error.', '{finops,purchasing,canonical}', NULL, 'internal', '{invoice_matches,invoice_match_lines,purchase_order_lines,goods_receipts}', NULL, '2026-08-04 21:27:58.28588+00') ON CONFLICT DO NOTHING;
INSERT INTO public.semantic_catalog ("id", "object_name", "column_name", "title", "description", "tags", "owner", "sensitivity", "source_tables", "iso_standard", "updated_at") VALUES ('eef48837-22aa-4aea-910b-9d121c74abd2', 'sem_invoice_matches', 'payables_status', 'Payables status', 'What a payables clerk should do with this invoice: cleared for payment, blocked with the reason, already paid, or not yet matched.', '{finops,kpi}', NULL, 'internal', '{invoice_matches}', NULL, '2026-08-04 21:27:58.28588+00') ON CONFLICT DO NOTHING;
