INSERT INTO public.audit_template_sections ("id", "template_id", "code", "title", "description", "sort_order", "weight", "standard_clause", "parent_section_id", "company_id") VALUES ('27359b3b-f7e1-4599-83f0-d7478e151fac', 'ccc08c35-eb57-4191-95a2-de68ce3fe5a3', 'RBI-06', 'Program Management & Reassessment', 'Data management, reassessment triggers, MOC integration, and continuous improvement.', '6', '1.00', 'API 580 §9-10', NULL, '7157991c-86c0-45b7-a0eb-ca36d83ac8dc') ON CONFLICT DO NOTHING;
INSERT INTO public.audit_template_questions ("id", "section_id", "code", "question_text", "guidance_notes", "evidence_expected", "question_type", "is_mandatory", "sort_order", "company_id") VALUES ('101238fa-ad46-4125-a606-3855ca093eaf', 'ad210943-cfdb-4bd3-a898-12eda370839d', 'P1.1', 'Is there a written plan of action for employee participation in PSM program development and conduct?', 'Verify documented plan exists and is communicated.', 'Written participation plan, communication records', 'maturity', 'true', '1', '7157991c-86c0-45b7-a0eb-ca36d83ac8dc') ON CONFLICT DO NOTHING;
INSERT INTO public.audit_template_questions ("id", "section_id", "code", "question_text", "guidance_notes", "evidence_expected", "question_type", "is_mandatory", "sort_order", "company_id") VALUES ('eaea7ece-ba9f-4c05-8a29-f3f4a36dc463', '9f5ffe3d-81a4-4409-8d35-1a6cce8d37f5', 'P4.1', 'Are written operating procedures in place that provide clear instructions for safely conducting activities for each covered process, including steps for each operating phase?', 'Procedures must cover: startup, normal, temporary, emergency shutdown, and startup after turnaround.', 'SOPs for each operating phase, procedure index', 'maturity', 'true', '1', '7157991c-86c0-45b7-a0eb-ca36d83ac8dc') ON CONFLICT DO NOTHING;
INSERT INTO public.audit_template_questions ("id", "section_id", "code", "question_text", "guidance_notes", "evidence_expected", "question_type", "is_mandatory", "sort_order", "company_id") VALUES ('d36a95d1-bb4c-46db-9683-be609ea25c6e', '9f5ffe3d-81a4-4409-8d35-1a6cce8d37f5', 'P4.2', 'Are operating procedures reviewed and certified annually as current and accurate?', 'Check annual review signatures and dates. Verify procedures reflect current operations.', 'Annual certification records, review signatures', 'maturity', 'true', '2', '7157991c-86c0-45b7-a0eb-ca36d83ac8dc') ON CONFLICT DO NOTHING;
INSERT INTO public.audit_template_questions ("id", "section_id", "code", "question_text", "guidance_notes", "evidence_expected", "question_type", "is_mandatory", "sort_order", "company_id") VALUES ('bd4358ad-ba10-42ac-8bea-59565ee67488', 'ff632a88-786e-46b2-8827-5a3597fe0bd0', 'P5.1', 'Is initial training provided to each employee currently involved in operating a covered process, emphasizing specific safety and health hazards, emergency operations, and safe work practices?', 'Training must be process-specific, not generic safety.', 'Training records, curricula, competency assessments', 'maturity', 'true', '1', '7157991c-86c0-45b7-a0eb-ca36d83ac8dc') ON CONFLICT DO NOTHING;
INSERT INTO public.audit_template_questions ("id", "section_id", "code", "question_text", "guidance_notes", "evidence_expected", "question_type", "is_mandatory", "sort_order", "company_id") VALUES ('a34f29c6-e0e0-4f10-9cae-c4dc7bb31266', 'cec3161b-e661-440e-adcd-b9acca2b3f7d', 'Q4.1', 'Has the organization determined external and internal issues relevant to its purpose and strategic direction that affect its ability to achieve the intended outcomes of its asset management system?', 'Look for: PESTLE analysis, strategic context documents, risk registers referencing external factors (regulatory, market, environmental).', 'Context analysis document, strategic plan, board minutes', 'maturity', 'true', '1', '7157991c-86c0-45b7-a0eb-ca36d83ac8dc') ON CONFLICT DO NOTHING;
INSERT INTO public.audit_template_questions ("id", "section_id", "code", "question_text", "guidance_notes", "evidence_expected", "question_type", "is_mandatory", "sort_order", "company_id") VALUES ('305fdc46-0731-460a-9a80-563d6e17bf3b', 'cec3161b-e661-440e-adcd-b9acca2b3f7d', 'Q4.2', 'Has the organization identified interested parties (stakeholders) relevant to the AMS and determined their needs and expectations?', 'Look for: Stakeholder register, needs analysis, communication plan.', 'Stakeholder register, engagement plan', 'maturity', 'true', '2', '7157991c-86c0-45b7-a0eb-ca36d83ac8dc') ON CONFLICT DO NOTHING;
INSERT INTO public.audit_template_questions ("id", "section_id", "code", "question_text", "guidance_notes", "evidence_expected", "question_type", "is_mandatory", "sort_order", "company_id") VALUES ('45b7e1a4-56ef-4f36-9276-226d774c30bd', 'cec3161b-e661-440e-adcd-b9acca2b3f7d', 'Q4.3', 'Is the scope of the AMS defined and documented, including boundaries and applicability?', 'The scope must consider asset types, lifecycle stages, organizational boundaries, and outsourced activities.', 'AMS scope statement, asset portfolio definition', 'maturity', 'true', '3', '7157991c-86c0-45b7-a0eb-ca36d83ac8dc') ON CONFLICT DO NOTHING;
INSERT INTO public.audit_template_questions ("id", "section_id", "code", "question_text", "guidance_notes", "evidence_expected", "question_type", "is_mandatory", "sort_order", "company_id") VALUES ('738da362-2460-4ed2-8054-748954e101fc', 'cec3161b-e661-440e-adcd-b9acca2b3f7d', 'Q4.4', 'Has the organization established, implemented, maintained and continually improved an asset management system?', 'Assess evidence of a systematic, documented AMS that covers policy, planning, support, operation, evaluation, and improvement.', 'AMS manual, process maps, management framework document', 'maturity', 'true', '4', '7157991c-86c0-45b7-a0eb-ca36d83ac8dc') ON CONFLICT DO NOTHING;
INSERT INTO public.audit_template_questions ("id", "section_id", "code", "question_text", "guidance_notes", "evidence_expected", "question_type", "is_mandatory", "sort_order", "company_id") VALUES ('a04d9856-631d-4d93-aedb-1bf637f89326', 'ad210943-cfdb-4bd3-a898-12eda370839d', 'P1.2', 'Do employees have access to PHA results, PSI, and other relevant PSM information?', 'Check accessibility of documents and awareness among operators.', 'Access records, employee interviews, document locations', 'maturity', 'true', '2', '7157991c-86c0-45b7-a0eb-ca36d83ac8dc') ON CONFLICT DO NOTHING;
INSERT INTO public.audit_template_questions ("id", "section_id", "code", "question_text", "guidance_notes", "evidence_expected", "question_type", "is_mandatory", "sort_order", "company_id") VALUES ('7b3e4036-0ec8-4004-9441-e1761b7ac8a6', '76dedaef-80fc-47eb-bd34-d70c285d1ef4', 'Q5.1.1', 'Does top management demonstrate leadership and commitment with respect to the asset management system?', 'Evidence of active involvement: chairing reviews, resource allocation, communicating importance of AM.', 'Management review minutes, resource allocation records, leadership communications', 'maturity', 'true', '1', '7157991c-86c0-45b7-a0eb-ca36d83ac8dc') ON CONFLICT DO NOTHING;
INSERT INTO public.audit_template_questions ("id", "section_id", "code", "question_text", "guidance_notes", "evidence_expected", "question_type", "is_mandatory", "sort_order", "company_id") VALUES ('c40110a5-c89c-4ea7-b337-9a8eacfcbeff', '76dedaef-80fc-47eb-bd34-d70c285d1ef4', 'Q5.1.2', 'Has top management ensured that the AM policy and objectives are compatible with the strategic direction of the organization?', 'Check alignment between organizational strategy, SAMP, and AM objectives.', 'Strategic plan, SAMP, AM objectives with traceability', 'maturity', 'true', '2', '7157991c-86c0-45b7-a0eb-ca36d83ac8dc') ON CONFLICT DO NOTHING;
INSERT INTO public.audit_template_questions ("id", "section_id", "code", "question_text", "guidance_notes", "evidence_expected", "question_type", "is_mandatory", "sort_order", "company_id") VALUES ('02d5ba48-7bb1-40d8-8660-310013244a73', '76dedaef-80fc-47eb-bd34-d70c285d1ef4', 'Q5.2', 'Is there a documented Asset Management Policy that is appropriate, provides a framework for objectives, includes commitment to continual improvement, and is communicated?', 'Policy must be signed by top management, reviewed periodically, and accessible to all relevant parties.', 'Signed AM policy, communication records, awareness evidence', 'maturity', 'true', '3', '7157991c-86c0-45b7-a0eb-ca36d83ac8dc') ON CONFLICT DO NOTHING;
INSERT INTO public.audit_template_questions ("id", "section_id", "code", "question_text", "guidance_notes", "evidence_expected", "question_type", "is_mandatory", "sort_order", "company_id") VALUES ('d5d099a7-fc3b-4959-8415-102d839308d3', '76dedaef-80fc-47eb-bd34-d70c285d1ef4', 'Q5.3', 'Are organizational roles, responsibilities and authorities for AM defined, assigned and communicated?', 'Look for: RACI matrices, job descriptions, organizational charts, competency frameworks.', 'RACI matrix, org chart, role descriptions, delegation of authority', 'maturity', 'true', '4', '7157991c-86c0-45b7-a0eb-ca36d83ac8dc') ON CONFLICT DO NOTHING;
INSERT INTO public.audit_template_questions ("id", "section_id", "code", "question_text", "guidance_notes", "evidence_expected", "question_type", "is_mandatory", "sort_order", "company_id") VALUES ('0c1c7a11-ffa3-4740-9950-c126276d1d2b', 'e275b528-c637-4e7d-9157-468a97df6a61', 'P2.1', 'Is there compiled PSI on the hazards of chemicals used or produced, including SDSs, permissible exposure limits, physical and reactivity data?', 'Verify completeness of chemical hazard data.', 'SDS library, chemical inventory, hazard data sheets', 'maturity', 'true', '1', '7157991c-86c0-45b7-a0eb-ca36d83ac8dc') ON CONFLICT DO NOTHING;
INSERT INTO public.audit_template_questions ("id", "section_id", "code", "question_text", "guidance_notes", "evidence_expected", "question_type", "is_mandatory", "sort_order", "company_id") VALUES ('227795aa-b68e-4660-bfef-66cb23805a5f', 'e275b528-c637-4e7d-9157-468a97df6a61', 'P2.2', 'Is process technology information documented including block flow diagrams, process chemistry, safe operating limits, and consequence of deviations?', 'Check for documented safe upper/lower limits for all critical parameters.', 'PFDs, P&IDs, operating envelopes, deviation matrices', 'maturity', 'true', '2', '7157991c-86c0-45b7-a0eb-ca36d83ac8dc') ON CONFLICT DO NOTHING;
INSERT INTO public.audit_template_questions ("id", "section_id", "code", "question_text", "guidance_notes", "evidence_expected", "question_type", "is_mandatory", "sort_order", "company_id") VALUES ('fb1e1768-0905-4496-9259-d5f96cd0e8e9', 'e275b528-c637-4e7d-9157-468a97df6a61', 'P2.3', 'Is equipment information documented including materials of construction, P&IDs, electrical classifications, relief system design, and ventilation system design?', 'Equipment data must be current and reflect as-built conditions.', 'Equipment data sheets, P&IDs (as-built), relief valve register', 'maturity', 'true', '3', '7157991c-86c0-45b7-a0eb-ca36d83ac8dc') ON CONFLICT DO NOTHING;
INSERT INTO public.audit_template_questions ("id", "section_id", "code", "question_text", "guidance_notes", "evidence_expected", "question_type", "is_mandatory", "sort_order", "company_id") VALUES ('f4db96f0-889d-4ad6-9404-5e86b2191949', 'a15fb2c1-83ce-4d2c-ac87-bc95edc0d3c3', 'Q6.1', 'Does the organization address risks and opportunities related to the AMS to ensure intended outcomes, prevent undesired effects, and achieve continual improvement?', 'Look for: Risk assessment methodology, risk register, opportunity identification process.', 'Risk register, risk assessment methodology, risk treatment plans', 'maturity', 'true', '1', '7157991c-86c0-45b7-a0eb-ca36d83ac8dc') ON CONFLICT DO NOTHING;
INSERT INTO public.audit_template_questions ("id", "section_id", "code", "question_text", "guidance_notes", "evidence_expected", "question_type", "is_mandatory", "sort_order", "company_id") VALUES ('e58ea4a8-6b33-4571-957b-c76f38812bf3', 'a15fb2c1-83ce-4d2c-ac87-bc95edc0d3c3', 'Q6.2.1', 'Has the organization established asset management objectives at relevant functions and levels, and are they measurable and consistent with the AM policy?', 'Objectives should be SMART, cascaded through the organization, and traceable to strategic objectives.', 'AM objectives register, KPIs, performance dashboards', 'maturity', 'true', '2', '7157991c-86c0-45b7-a0eb-ca36d83ac8dc') ON CONFLICT DO NOTHING;
INSERT INTO public.audit_template_questions ("id", "section_id", "code", "question_text", "guidance_notes", "evidence_expected", "question_type", "is_mandatory", "sort_order", "company_id") VALUES ('dc483bba-5637-4892-b8a4-cabf45f08c58', 'a15fb2c1-83ce-4d2c-ac87-bc95edc0d3c3', 'Q6.2.2', 'Is there a Strategic Asset Management Plan (SAMP) that documents how organizational objectives translate to AM objectives?', 'The SAMP is the cornerstone document. It must link organizational strategy to AM activities, lifecycle decisions, and resource plans.', 'SAMP document, line-of-sight traceability matrix', 'maturity', 'true', '3', '7157991c-86c0-45b7-a0eb-ca36d83ac8dc') ON CONFLICT DO NOTHING;
INSERT INTO public.audit_template_questions ("id", "section_id", "code", "question_text", "guidance_notes", "evidence_expected", "question_type", "is_mandatory", "sort_order", "company_id") VALUES ('1d64956d-aac6-4617-9c88-8bb591cfc2ba', 'a15fb2c1-83ce-4d2c-ac87-bc95edc0d3c3', 'Q6.2.3', 'Are there documented AM plans that specify activities, resources, responsibilities, timeframes, and methods to achieve AM objectives?', 'AM plans translate objectives into operational activities. Check for maintenance strategies, capital plans, lifecycle plans.', 'AM plans, capital investment plans, maintenance strategy documents', 'maturity', 'true', '4', '7157991c-86c0-45b7-a0eb-ca36d83ac8dc') ON CONFLICT DO NOTHING;
INSERT INTO public.audit_template_questions ("id", "section_id", "code", "question_text", "guidance_notes", "evidence_expected", "question_type", "is_mandatory", "sort_order", "company_id") VALUES ('c86148b4-1d68-42fb-950e-8e064d0221fc', '046a94f7-887e-4523-840b-fe7358eedd9b', 'P3.1', 'Has the employer performed an initial PHA appropriate to the complexity of the process using a recognized methodology (HAZOP, What-If, Checklist, FMEA)?', 'Verify methodology is appropriate for process complexity. HAZOP preferred for complex processes.', 'PHA reports, methodology selection rationale', 'maturity', 'true', '1', '7157991c-86c0-45b7-a0eb-ca36d83ac8dc') ON CONFLICT DO NOTHING;
INSERT INTO public.audit_template_questions ("id", "section_id", "code", "question_text", "guidance_notes", "evidence_expected", "question_type", "is_mandatory", "sort_order", "company_id") VALUES ('ea6454d9-466a-4083-9718-bea0282c4edf', '046a94f7-887e-4523-840b-fe7358eedd9b', 'P3.2', 'Does the PHA address hazards of the process, previous incidents, engineering and administrative controls, consequences of failure, facility siting, human factors, and qualitative evaluation of safeguards?', 'Each PHA must cover all mandatory topics per 1910.119(e)(2).', 'PHA worksheets covering all required topics', 'maturity', 'true', '2', '7157991c-86c0-45b7-a0eb-ca36d83ac8dc') ON CONFLICT DO NOTHING;
INSERT INTO public.audit_template_questions ("id", "section_id", "code", "question_text", "guidance_notes", "evidence_expected", "question_type", "is_mandatory", "sort_order", "company_id") VALUES ('5f93f4be-72b5-45e2-81dc-76e18e256968', '046a94f7-887e-4523-840b-fe7358eedd9b', 'P3.3', 'Are PHAs updated and revalidated at least every 5 years?', 'Check revalidation dates against 5-year cycle. Verify methodology and team composition.', 'PHA revalidation schedule, completed revalidation reports', 'maturity', 'true', '3', '7157991c-86c0-45b7-a0eb-ca36d83ac8dc') ON CONFLICT DO NOTHING;
INSERT INTO public.audit_template_questions ("id", "section_id", "code", "question_text", "guidance_notes", "evidence_expected", "question_type", "is_mandatory", "sort_order", "company_id") VALUES ('ad593914-cae8-4c43-a0e0-fb61834e81fb', '046a94f7-887e-4523-840b-fe7358eedd9b', 'P3.4', 'Are PHA recommendations resolved and documented in a timely manner?', 'Track action item closure rates and overdue items.', 'Action tracking register, closure rates, overdue analysis', 'maturity', 'true', '4', '7157991c-86c0-45b7-a0eb-ca36d83ac8dc') ON CONFLICT DO NOTHING;
INSERT INTO public.audit_template_questions ("id", "section_id", "code", "question_text", "guidance_notes", "evidence_expected", "question_type", "is_mandatory", "sort_order", "company_id") VALUES ('5c89d128-b997-4ffa-b64f-32b33db096c6', 'a1d947fa-4026-4566-9604-41a544257285', 'Q7.1', 'Has the organization determined and provided the resources needed for the AMS?', 'Resources include: people, tools, technology (EAM/CMMS), budget, infrastructure.', 'Resource plans, budgets, technology roadmap, staffing plans', 'maturity', 'true', '1', '7157991c-86c0-45b7-a0eb-ca36d83ac8dc') ON CONFLICT DO NOTHING;
INSERT INTO public.audit_template_questions ("id", "section_id", "code", "question_text", "guidance_notes", "evidence_expected", "question_type", "is_mandatory", "sort_order", "company_id") VALUES ('8a1b3270-b707-40b4-9430-2dcfc30a9413', 'a1d947fa-4026-4566-9604-41a544257285', 'Q7.2', 'Has the organization determined necessary competence, ensured persons are competent, and taken action to acquire competence where needed?', 'Look for: Competency frameworks, training plans, qualification records, certification tracking.', 'Competency matrix, training records, certification database', 'maturity', 'true', '2', '7157991c-86c0-45b7-a0eb-ca36d83ac8dc') ON CONFLICT DO NOTHING;
INSERT INTO public.audit_template_questions ("id", "section_id", "code", "question_text", "guidance_notes", "evidence_expected", "question_type", "is_mandatory", "sort_order", "company_id") VALUES ('11c1484f-42ef-426c-8c11-02223a0f33d9', 'a1d947fa-4026-4566-9604-41a544257285', 'Q7.3', 'Are relevant persons aware of the AM policy, their contribution to AMS effectiveness, and implications of non-conformance?', 'Check for awareness programs, induction processes, toolbox talks, AM communications.', 'Awareness records, induction checklists, communication logs', 'maturity', 'true', '3', '7157991c-86c0-45b7-a0eb-ca36d83ac8dc') ON CONFLICT DO NOTHING;
INSERT INTO public.audit_template_questions ("id", "section_id", "code", "question_text", "guidance_notes", "evidence_expected", "question_type", "is_mandatory", "sort_order", "company_id") VALUES ('5a142508-56b8-467d-ad27-28b28acb9455', 'a1d947fa-4026-4566-9604-41a544257285', 'Q7.5', 'Does the organization control documented information required by the AMS, including creation, update, and control of documents?', 'Document control process, version management, accessibility, retention policies.', 'Document management system, document register, control procedures', 'maturity', 'true', '4', '7157991c-86c0-45b7-a0eb-ca36d83ac8dc') ON CONFLICT DO NOTHING;
INSERT INTO public.audit_template_questions ("id", "section_id", "code", "question_text", "guidance_notes", "evidence_expected", "question_type", "is_mandatory", "sort_order", "company_id") VALUES ('aaafbca9-dfaa-4551-86a9-82d0b4489f70', '26156064-d6cf-481e-87c8-e558b6502b76', 'Q8.1', 'Does the organization plan, implement and control processes needed to meet AM objectives and implement actions from planning?', 'Look for: Work management processes (WO system), preventive/predictive maintenance programs, lifecycle delivery processes.', 'Work management procedures, PM/PdM programs, WO completion data', 'maturity', 'true', '1', '7157991c-86c0-45b7-a0eb-ca36d83ac8dc') ON CONFLICT DO NOTHING;
INSERT INTO public.audit_template_questions ("id", "section_id", "code", "question_text", "guidance_notes", "evidence_expected", "question_type", "is_mandatory", "sort_order", "company_id") VALUES ('ca52183b-47be-4e10-921f-f38e5ee5dc9a', '26156064-d6cf-481e-87c8-e558b6502b76', 'Q8.2', 'Has the organization established processes for Management of Change to evaluate and manage risks from planned and unplanned changes?', 'MOC process must cover: asset modifications, organizational changes, technology changes, regulatory changes.', 'MOC procedure, MOC register, change impact assessments', 'maturity', 'true', '2', '7157991c-86c0-45b7-a0eb-ca36d83ac8dc') ON CONFLICT DO NOTHING;
