INSERT INTO public.audit_template_questions ("id", "section_id", "code", "question_text", "guidance_notes", "evidence_expected", "question_type", "is_mandatory", "sort_order", "company_id") VALUES ('0a4c8158-cea0-4c65-a78f-579c7b55c4a9', '8242d04d-15ef-4c43-a919-faa1fa2ac8ea', 'Q9.2', 'Does the organization conduct internal audits at planned intervals to provide information on AMS conformity and effectiveness?', 'Audit program, trained auditors, audit reports, finding closure tracking.', 'Audit program, audit reports, auditor qualifications, finding register', 'maturity', 'true', '2', '7157991c-86c0-45b7-a0eb-ca36d83ac8dc') ON CONFLICT DO NOTHING;
