INSERT INTO public.audit_template_questions ("id", "section_id", "code", "question_text", "guidance_notes", "evidence_expected", "question_type", "is_mandatory", "sort_order", "company_id") VALUES ('c81664ac-e8cb-4f94-8323-aecda4e22321', '3665e1f6-7563-440f-a9ad-2fbe58697a6d', 'Q10.1', 'When a nonconformity occurs, does the organization react, evaluate the need for corrective action, implement actions, and review their effectiveness?', 'Root cause analysis, CAPA process, effectiveness verification, trend analysis of nonconformities.', 'NCR register, RCA reports, CAPA records, effectiveness reviews', 'maturity', 'true', '1', '7157991c-86c0-45b7-a0eb-ca36d83ac8dc') ON CONFLICT DO NOTHING;
