INSERT INTO public.audit_template_questions ("id", "section_id", "code", "question_text", "guidance_notes", "evidence_expected", "question_type", "is_mandatory", "sort_order", "company_id") VALUES ('e7567dd0-d7a7-493a-bd9d-85f710f3b6da', '0c1a816f-15c3-4867-93c3-571f4a3aa2af', 'P9.1', 'Is a hot work permit issued for all hot work operations conducted on or near a covered process, documenting fire prevention and protection requirements?', 'Verify permit content, authorization, fire watch requirements, and atmospheric monitoring.', 'Hot work permits, fire watch logs, atmospheric test records', 'maturity', 'true', '1', '7157991c-86c0-45b7-a0eb-ca36d83ac8dc') ON CONFLICT DO NOTHING;
INSERT INTO public.audit_template_questions ("id", "section_id", "code", "question_text", "guidance_notes", "evidence_expected", "question_type", "is_mandatory", "sort_order", "company_id") VALUES ('a40ac122-e4ec-44b3-bee4-0f93888b7cb1', '3a12a03d-72f1-45eb-b290-c18768aab32a', 'R1.1', 'Is there a documented RBI program with defined scope, objectives, and governance structure?', 'Look for: RBI procedure document, program charter, management endorsement, defined scope of equipment.', 'RBI program document, management endorsement, scope definition', 'maturity', 'true', '1', '7157991c-86c0-45b7-a0eb-ca36d83ac8dc') ON CONFLICT DO NOTHING;
