INSERT INTO public.audit_template_questions ("id", "section_id", "code", "question_text", "guidance_notes", "evidence_expected", "question_type", "is_mandatory", "sort_order", "company_id") VALUES ('6c513ddc-a9ca-4300-a5d8-951b3cf4cd35', '3a12a03d-72f1-45eb-b290-c18768aab32a', 'R1.3', 'Is the RBI assessment methodology documented and consistently applied (qualitative, semi-quantitative, or quantitative)?', 'Verify methodology selection rationale and consistent application across equipment groups.', 'RBI methodology document, assessment worksheets, software configuration', 'maturity', 'true', '3', '7157991c-86c0-45b7-a0eb-ca36d83ac8dc') ON CONFLICT DO NOTHING;
INSERT INTO public.audit_template_questions ("id", "section_id", "code", "question_text", "guidance_notes", "evidence_expected", "question_type", "is_mandatory", "sort_order", "company_id") VALUES ('99f6ffd5-3cd6-4d36-9492-6585e8bb9904', '13863915-7077-401f-94de-7d40ba49c383', 'R2.1', 'Are consequence categories defined and evaluated for safety (flammable, toxic, asphyxiant), environmental (spill volume, receptor proximity), and financial (production loss, repair cost)?', 'Each equipment item must have consequence ratings for all three categories.', 'Consequence analysis worksheets, release scenario modeling', 'maturity', 'true', '1', '7157991c-86c0-45b7-a0eb-ca36d83ac8dc') ON CONFLICT DO NOTHING;
