INSERT INTO public.audit_template_questions ("id", "section_id", "code", "question_text", "guidance_notes", "evidence_expected", "question_type", "is_mandatory", "sort_order", "company_id") VALUES ('133cc008-046b-4d3a-9e31-8c4314ae7ccd', '27a311a7-5c74-4a00-9c17-737c7c6907d9', 'R5.1', 'Are pressure vessels inspected per API 510 requirements, including internal/external inspections within maximum intervals, and is an authorized inspector involved?', 'API 510: Internal inspection max 10 years (or ½ remaining life). External max 5 years. CRO provisions if applicable.', 'API 510 compliance matrix, inspection records, AI qualifications', 'maturity', 'true', '1', '7157991c-86c0-45b7-a0eb-ca36d83ac8dc') ON CONFLICT DO NOTHING;
