INSERT INTO public.audit_template_questions ("id", "section_id", "code", "question_text", "guidance_notes", "evidence_expected", "question_type", "is_mandatory", "sort_order", "company_id") VALUES ('5b99f28a-720f-477f-b78c-a3acec169d28', '1f7d31e2-25a0-4274-8cd8-8725f046d0c8', 'R3.2', 'Are corrosion rates established based on inspection data, and are they used to calculate remaining life and probability of failure?', 'Check corrosion rate sources: UT thickness data, coupon data, process modeling. Verify statistical confidence.', 'Corrosion rate database, UT trending data, remaining life calculations', 'maturity', 'true', '2', '7157991c-86c0-45b7-a0eb-ca36d83ac8dc') ON CONFLICT DO NOTHING;
INSERT INTO public.audit_template_questions ("id", "section_id", "code", "question_text", "guidance_notes", "evidence_expected", "question_type", "is_mandatory", "sort_order", "company_id") VALUES ('77660324-0459-421a-aaff-214c958b482c', '1f7d31e2-25a0-4274-8cd8-8725f046d0c8', 'R3.3', 'Is inspection effectiveness categorized (A through E per API 581) and factored into probability calculations?', 'Each inspection event should be rated for effectiveness. Higher effectiveness reduces PoF.', 'Inspection effectiveness ratings, PoF adjustment calculations', 'maturity', 'true', '3', '7157991c-86c0-45b7-a0eb-ca36d83ac8dc') ON CONFLICT DO NOTHING;
INSERT INTO public.audit_template_questions ("id", "section_id", "code", "question_text", "guidance_notes", "evidence_expected", "question_type", "is_mandatory", "sort_order", "company_id") VALUES ('921bcff4-eeb2-4c99-9ccb-869fb87e2cd1', '0bbf4f63-9d3f-4397-8fe7-93b50a60123c', 'R4.1', 'Is a risk matrix or risk ranking system used to prioritize equipment for inspection, with defined risk acceptance criteria?', 'Check risk matrix dimensions, color coding, and management-approved acceptance thresholds.', 'Risk matrix, acceptance criteria document, ranked equipment list', 'maturity', 'true', '1', '7157991c-86c0-45b7-a0eb-ca36d83ac8dc') ON CONFLICT DO NOTHING;
INSERT INTO public.audit_template_questions ("id", "section_id", "code", "question_text", "guidance_notes", "evidence_expected", "question_type", "is_mandatory", "sort_order", "company_id") VALUES ('5f682cb8-2cdf-47cb-9ce1-25409c1de9c1', '0bbf4f63-9d3f-4397-8fe7-93b50a60123c', 'R4.2', 'Are inspection plans developed based on RBI results, specifying inspection scope, methods, coverage, and intervals?', 'Plans must specify: NDE methods, CML locations, coverage %, scheduled dates, and effectiveness targets.', 'Inspection plans per equipment, NDE procedure specifications', 'maturity', 'true', '2', '7157991c-86c0-45b7-a0eb-ca36d83ac8dc') ON CONFLICT DO NOTHING;
INSERT INTO public.audit_template_questions ("id", "section_id", "code", "question_text", "guidance_notes", "evidence_expected", "question_type", "is_mandatory", "sort_order", "company_id") VALUES ('060706de-f9f2-4264-93a8-8411d28cc956', '37530c48-a4e0-4aef-95b2-31fb272846f8', 'P14.1', 'Does the employer make all information necessary to comply with the PSM standard available to those persons responsible for compiling PSI, PHA, and other PSM elements, regardless of trade secret claims?', 'Verify that trade secret protections do not impede PSM compliance activities.', 'Confidentiality agreements, access records, information sharing policy', 'maturity', 'true', '1', '7157991c-86c0-45b7-a0eb-ca36d83ac8dc') ON CONFLICT DO NOTHING;
